<script setup>import {ref,watch} from 'vue';const props=defineProps({modelValue:Number});const emit=defineEmits(['update:modelValue','save']);const local=ref(props.modelValue);watch(()=>props.modelValue,v=>local.value=v);function save(){emit('update:modelValue',Number(local.value));emit('save')}</script><template><form class="goal-editor" @submit.prevent="save"><span class="goal-icon">◎</span><div class="goal-copy"><b>每日学习时长目标</b><small>设定适合自己的小目标。</small></div><input v-model.number="local" type="number" min="15" max="720" step="15"/><span>分钟 / 天</span><button class="primary">保存目标</button></form></template>